function in_ice = flag_icespectra(f, E, Hs, Tp, f_fit)
%  Identify wave spectra consistent with sea ice cover with no measurable
%  surface waves. Inputs f, E, Hs, and Tp can be generated by UVZwaves.m 
%
%  Inputs:
%     f       - Frequency vector [Hz]
%     E       - Surface elevation power spectral density vector [m^2/Hz]
%     Hs      - Significant wave height [m]
%     Tp      - Peak wave period [s]
%     f_fit   - Lower frequency limit for spectral tail fit [Hz]
%  
%  Output: 
%     in_ice  - True if observation flagged as collected in sea ice
%
%  L. Crews, Nov 2026

% Parameters used to identify spectra indicating buoy in sea ice with no waves
minwaveheight_ice = 0.1; %Approx microswift noise floor
maxwaveperiod = 20; % max wave period, usually 20 s
maxtailshapeexponent = -2.5;  % max value for f^q in the tail, theoretically -4
min_spectral_energy_ratio = 0.35; % Value determined experimentally from PISCES 2026 microSWIFT deployments. Expect open water w/ no ice to have high ratio (higher energy in wave band, lower energy at low frequency)

in_ice = false; % default flag value

% Fit tail shape above specified frequency
x = log(f(f>=f_fit & f<=0.5));
y = log(E(f>=f_fit & f<=0.5));
bt = polyfit(x, y, 1);
tailshape = bt(1);

% Also filter based on ratio of high:low frequency energy (using a
% relatively broad frequency band for "high"/wave band energy)
spec_energy_ratio = mean(E(f>=0.1 & f<=0.5)) / mean(E(f<=0.1));
    
% Suspect buoy is in sea ice with no waves
if tailshape > maxtailshapeexponent | Hs < minwaveheight_ice | Tp > maxwaveperiod | spec_energy_ratio < min_spectral_energy_ratio
    in_ice = true;
end

end